-- Costo: 5.831 cr; filas: 463; engine medium
-- Generated by scripts/activity_sql.py. Archive, incremental: previous snapshot of this matview
-- plus, on the first Monday of the month only, the month that just closed.
WITH prev AS (SELECT * FROM dune.paltalabs.result_scf_xoxno_lending_activity_archive WHERE row_kind = 'activity'),
src AS (
WITH codes AS (SELECT * FROM (VALUES
    (0, 'supply', 'lender'),
    (2, 'withdraw', 'lender'),
    (9, 'swap_collateral_withdraw', 'lender'),
    (10, 'repay_collateral_withdraw', 'lender'),
    (12, 'close_withdraw', 'lender'),
    (1, 'borrow', 'borrower'),
    (3, 'repay', 'borrower'),
    (6, 'multiply', 'borrower'),
    (8, 'swap_debt', 'borrower'),
    (11, 'repay_collateral_repay', 'borrower'),
    (13, 'migrate_from_blend', 'borrower'),
    (14, 'repay_collateral_net', 'borrower'),
    (16, 'flash_position', 'borrower')) AS v(code, action, role)),
ev AS (
  SELECT DISTINCT he.contract_id, he.closed_at, lower(to_hex(he.transaction_hash)) AS tx_hash,
    CASE WHEN he.contract_id = 'CAWCSG77AY2W24QZ6ZXLHZU4UXEFHZBM6EI4A4IF7JB5CTY4XND3TI6C' THEN 'nft_transfer'
         ELSE json_extract_scalar(he.topics_decoded, '$[1].symbol') END AS kind,
    he.topics_decoded, he.data_decoded
  FROM stellar.history_contract_events he
  WHERE he.closed_at_date >= CURRENT_DATE - INTERVAL '75' DAY AND he.closed_at_date >= (SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_lending_activity_archive WHERE row_kind = 'metadata') AND he.closed_at_date < CAST(date_trunc('month', CURRENT_DATE) AS DATE) AND day_of_month(CURRENT_DATE) <= 7
    AND he.contract_id IN ('CAUCMIN5KSXEVZ7NMXR3LZATGD5EFIEUI5XWTFLYRO2R5OTXI22WE5JX', 'CAWCSG77AY2W24QZ6ZXLHZU4UXEFHZBM6EI4A4IF7JB5CTY4XND3TI6C')
    AND he.type_string = 'ContractEventTypeContract'
    AND he.successful = TRUE AND he.in_successful_contract_call = TRUE
    AND ((he.contract_id = 'CAUCMIN5KSXEVZ7NMXR3LZATGD5EFIEUI5XWTFLYRO2R5OTXI22WE5JX' AND json_extract_scalar(he.topics_decoded, '$[0].symbol') = 'position'
          AND json_extract_scalar(he.topics_decoded, '$[1].symbol') IN ('batch_update', 'liquidation', 'flash_loan'))
      OR (he.contract_id = 'CAWCSG77AY2W24QZ6ZXLHZU4UXEFHZBM6EI4A4IF7JB5CTY4XND3TI6C' AND json_extract_scalar(he.topics_decoded, '$[0].symbol') = 'transfer'))
),
legs AS (
  SELECT e.contract_id, e.closed_at, e.tx_hash,
    json_extract_scalar(e.data_decoded, '$.vec[1].vec[0].address') AS user_address,
    TRY(CAST(json_extract_scalar(t.leg, '$.vec[0].u32') AS INTEGER)) AS code,
    json_extract_scalar(t.leg, '$.vec[2].address') AS asset,
    COALESCE(
      TRY(CAST(json_extract_scalar(t.leg, '$.vec[5].i128') AS DECIMAL(38,0))),
      TRY(CAST(json_extract_scalar(t.leg, '$.vec[5].i128.hi') AS DECIMAL(38,0)) * DECIMAL '18446744073709551616'
          + CAST(json_extract_scalar(t.leg, '$.vec[5].i128.lo') AS DECIMAL(38,0)))) AS raw
  FROM ev e
  CROSS JOIN UNNEST(CAST(json_extract(e.data_decoded, '$.vec[2].vec') AS array(json))
                 || CAST(json_extract(e.data_decoded, '$.vec[3].vec') AS array(json))) AS t(leg)
  WHERE e.kind = 'batch_update'
),
acts AS (
  SELECT l.contract_id, l.closed_at, l.tx_hash, l.user_address, c.action, c.role, l.asset, l.raw
  FROM legs l JOIN codes c ON c.code = l.code
  UNION ALL
  SELECT contract_id, closed_at, tx_hash, regexp_extract(data_decoded, '"liquidator"\},"val":\{"address":"?([GC][A-Z2-7]{55})', 1), 'liquidate', 'liquidator', NULL, NULL
  FROM ev WHERE kind = 'liquidation'
  UNION ALL
  SELECT contract_id, closed_at, tx_hash, regexp_extract(data_decoded, '"caller"\},"val":\{"address":"?([GC][A-Z2-7]{55})', 1), 'flash_loan', 'borrower',
    regexp_extract(data_decoded, '"asset"\},"val":\{"address":"?([GC][A-Z2-7]{55})', 1), TRY(CAST(regexp_extract(data_decoded, '"amount"\},"val":\{"i128":"?(-?[0-9]+)', 1) AS DECIMAL(38,0)))
  FROM ev WHERE kind = 'flash_loan'
  UNION ALL
  SELECT contract_id, closed_at, tx_hash, json_extract_scalar(topics_decoded, '$[2].address'), 'position_transfer', 'position_holder',
    NULL, NULL
  FROM ev WHERE kind = 'nft_transfer'
)
SELECT 'xoxno_lending' AS protocol, contract_id, closed_at, tx_hash, user_address, action, role,
  CAST(NULL AS VARCHAR) AS pool, asset AS token_a, CAST(raw * DECIMAL '0.0000001' AS DECIMAL(38,7)) AS amount_a,
  CAST(NULL AS VARCHAR) AS token_b, CAST(NULL AS DECIMAL(38,7)) AS amount_b
FROM acts
)
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, role, pool, token_a, amount_a, token_b, amount_b,
       'activity' AS row_kind, covered_from, CASE WHEN day_of_month(CURRENT_DATE) <= 7 THEN GREATEST((SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_lending_activity_archive WHERE row_kind = 'metadata'), CAST(date_trunc('month', CURRENT_DATE) AS DATE)) ELSE (SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_lending_activity_archive WHERE row_kind = 'metadata') END AS covered_until, refreshed_at, source_layer
FROM prev
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, role, pool, token_a, amount_a, token_b, amount_b,
       'activity', DATE '2026-08-01', CASE WHEN day_of_month(CURRENT_DATE) <= 7 THEN GREATEST((SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_lending_activity_archive WHERE row_kind = 'metadata'), CAST(date_trunc('month', CURRENT_DATE) AS DATE)) ELSE (SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_lending_activity_archive WHERE row_kind = 'metadata') END, CURRENT_TIMESTAMP, 'archive'
FROM src
WHERE regexp_like(user_address, '^[GC][A-Z2-7]{55}$') AND role IS NOT NULL
UNION ALL
SELECT 'xoxno_lending', NULL, CAST(NULL AS TIMESTAMP WITH TIME ZONE), NULL, NULL, NULL, NULL, NULL, NULL, CAST(NULL AS DECIMAL(38,7)), NULL, CAST(NULL AS DECIMAL(38,7)),
       'metadata', DATE '2026-08-01', CASE WHEN day_of_month(CURRENT_DATE) <= 7 THEN GREATEST((SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_lending_activity_archive WHERE row_kind = 'metadata'), CAST(date_trunc('month', CURRENT_DATE) AS DATE)) ELSE (SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_lending_activity_archive WHERE row_kind = 'metadata') END, CURRENT_TIMESTAMP, 'archive'
